ALLOWED = {"click", "type", "scroll"}

def act_with_verify(page, action, expect, max_wait_ms=8000):
    snap = page.snapshot()
    if action.snapshot_id != snap.id:
        return {"status": "stale_snapshot"}          # 快照过期，重拍再决策
    if action.kind not in ALLOWED:
        return {"status": "rejected"}

    before = page.signature(action.target)
    page.dispatch(action)

    if page.wait_until(lambda: expect.match(page), timeout=max_wait_ms):
        return {"status": "ok"}
    if page.signature(action.target) == before:
        return {"status": "failed"}                 # 明确无变化，可有限重试
    return {"status": "unknown", "need": "reconcile"}  # 有变化未达预期，禁止重放

def judge_once(client, q, a, b, rubric):
    prompt = f"{rubric}\n问题: {q}\n候选A: {a}\n候选B: {b}\n只输出 A 或 B"
    out = client.chat(prompt, temperature=0, seed=7, max_tokens=4)
    return "A" if out.strip().upper().startswith("A") else "B"

def pair_score(client, q, new, base, rubric, k=3):
    win = 0.0
    for _ in range(k):
        fwd = judge_once(client, q, new, base, rubric)
        rev = judge_once(client, q, base, new, rubric)
        if fwd == "A" and rev == "B":
            win += 1.0          # 两次都判新答案好
        elif fwd == "B" and rev == "A":
            win += 0.0
        else:
            win += 0.5          # 顺序不一致记平局
    return win / k

import asyncio
from collections import defaultdict

def rrf(rank_lists, k=60, weights=None):
    weights = weights or [1.0] * len(rank_lists)
    score = defaultdict(float)
    for w, ranked in zip(weights, rank_lists):
        for pos, doc_id in enumerate(ranked):
            score[doc_id] += w / (k + pos + 1)
    return sorted(score, key=score.get, reverse=True)

async def dual_query_search(q, retriever, translator, budget=0.25, top_k=10):
    orig = await retriever.dense(q, top_k=50)
    try:
        en = await asyncio.wait_for(translator(q), timeout=budget)
    except Exception:
        return orig[:top_k]
    trans = await retriever.dense(en, top_k=50)
    lexical = await retriever.bm25(en, top_k=50, analyzer="en")
    return rrf([orig, trans, lexical], weights=[1.0, 1.0, 0.6])[:top_k]

import asyncio, hashlib
from dataclasses import dataclass, field

@dataclass
class SearchBudget:
    max_calls: int = 3
    timeout_s: float = 2.0
    calls: int = 0
    cache: dict = field(default_factory=dict)

def norm(q, filters):
    raw = q.strip().lower() + repr(sorted((filters or {}).items()))
    return hashlib.md5(raw.encode()).hexdigest()

async def search_knowledge(query, top_k=5, filters=None, budget=None):
    key = norm(query, filters)
    if key in budget.cache:
        return {**budget.cache[key], "status": "cached",
                "hint": "同一 query 已检索过，请基于已有证据作答或换更具体的问法"}
    if budget.calls >= budget.max_calls:
        return {"status": "budget_exhausted", "hits": [],
                "hint": "检索次数已达上限，请基于已有证据回答或说明无法确认"}
    budget.calls += 1
    try:
        hits = await asyncio.wait_for(index.search(query, top_k, filters), budget.timeout_s)
    except asyncio.TimeoutError:
        return {"status": "timeout", "hits": [], "hint": "检索超时，不等于没有该信息"}
    res = {"status": "ok" if hits else "no_match",
           "max_score": max((h.score for h in hits), default=0.0),
           "hits": [{"chunk_id": h.id, "text": h.text[:400], "score": h.score} for h in hits]}
    budget.cache[key] = res
    return res

